const data=[{name:'Mariana Torres',company:'Studio Norte',source:'Meta Ads',value:18500,stage:'qualified'},{name:'Carlos Méndez',company:'Data House',source:'Google',value:32000,stage:'proposal'},{name:'Sofía Lara',company:'Lara Arquitectura',source:'Orgánico',value:12000,stage:'new'},{name:'Diego Ramírez',company:'Logística D3',source:'Referido',value:45000,stage:'won'}];let stage='all';const $=s=>document.querySelector(s);function render(){const q=$('#search').value.toLowerCase();const rows=data.filter(x=>(stage==='all'||x.stage===stage)&&`${x.name} ${x.company}`.toLowerCase().includes(q));$('#leads').innerHTML=rows.map(x=>`<article class="card"><div class="card-head"><span class="avatar">${x.name.split(' ').map(w=>w[0]).slice(0,2).join('')}</span><span class="stage ${x.stage}">${x.stage}</span></div><h2>${x.name}</h2><p>${x.company}</p><div class="card-foot"><span>${x.source}</span><b>$${x.value.toLocaleString('es-MX')}</b></div></article>`).join('')||'<p style="color:#91a6bb">Sin coincidencias.</p>'}$('#search').addEventListener('input',render);document.querySelectorAll('.filter').forEach(btn=>btn.addEventListener('click',()=>{stage=btn.dataset.stage;document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));btn.classList.add('active');render()}));render();
